import numpy as np

grid = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])
rows, cols = grid.shape

# Let's look for periodic patterns
# Check if grid can be decomposed into smaller repeating patterns

def find_periodic_pattern(arr):
    """Find if an array has a repeating pattern"""
    if arr.ndim == 1:
        n1, n2 = arr.shape
        for p in range(1, n1//2 + 1):
            if n1 % p == 0:
                tile = arr[:p]
                if np.all(arr == np.tile(tile, n1//p)):
                    return (1, p)
        return None
    elif arr.ndim == 2:
        h, w = arr.shape
        for ph in range(1, h//2 + 1):
            for pw in range(1, w//2 + 1):
                if h % ph == 0 and w % pw == 0:
                    tile = arr[:ph, :pw]
                    repeat = np.tile(tile, (h//ph, w//pw))
                    if np.all(arr == repeat):
                        return (ph, pw)
        return None

# Check 1D periodicity along rows and columns
print("1D periodicity in rows:")
for r in range(rows):
    period = find_periodic_pattern(grid[r])
    if period:
        print(f"  Row {r}: period {period}, shift={period[1]}")

print("\n1D periodicity in columns:")
for c in range(cols):
    period = find_periodic_pattern(grid[:, c])
    if period:
        print(f"  Col {c}: period {period}, shift={period[1]}")

# Let's look at it differently - maybe it's a generated pattern
# from some rule like cellular automaton

# Check first few rows for hints
print("\n--- First 5 rows ---")
for i in range(5):
    print(f"Row {i}: {grid[i][:20].tolist()}...")

print("\n--- Last 5 rows ---")
for i in range(rows-5, rows):
    print(f"Row {i}: {grid[i][:20].tolist()}...")

# Maybe there's a relation between rows
# Check if each row is derived from previous row
print("\n--- Row differences ---")
for i in range(1, min(10, rows)):
    row_diff = np.sum(grid[i] != grid[i-1])
    print(f"Row {i} vs {i-1}: {row_diff} differences")

# Check if columns can be mapped to each other
print("\n--- Column comparison ---")
unique_cols = []
for c in range(cols):
    is_new = True
    for existing in unique_cols:
        if np.array_equal(grid[:, c], grid[:, existing]):
            is_new = False
            break
    if is_new:
        unique_cols.append(c)
print(f"Number of unique columns: {len(unique_cols)} out of {cols}")
print(f"Unique cols indices: {unique_cols}")

# Let's see if columns have the same pattern but shifted
print("\n--- Column shifts ---")
for c1 in unique_cols:
    col1 = grid[:, c1]
    for c2 in unique_cols:
        col2 = grid[:, c2]
        if c1 < c2:
            # Check if col2 is shifted version of col1
            max_shift = min(rows, len(col2))
            matches = 0
            for shift in range(max_shift):
                if np.array_equal(col1[:rows-shift], col2[shift:]):
                    matches += 1
            if matches > 0:
                print(f"  Col {c2} matches Col {c1} with shift {matches//2}")

# Let me try to understand by looking at the structure more carefully
# Divide into blocks and see if there's a pattern
print("\n--- Block analysis ---")
# Try dividing into various block sizes
for b in range(4, 13):
    if rows % b == 0 and cols % b == 0:
        print(f"\nTrying {b}x{b} blocks:")
        tile = grid[:b, :b]
        matches = True
        tile_str = str(tile.tolist())
        for i in range(0, rows, b):
            for j in range(0, cols, b):
                block = grid[i:i+b, j:j+b]
                if str(block.tolist()) != tile_str:
                    matches = False
                    break
            if not matches:
                break
        if matches:
            print(f"  Found {b}x{b} repeating tile!")

